 * Assigns the owner's {@code bulkSignupWarning}: {@code true} when more than 80 owners
 * have already been created on the new owner's effective business day, otherwise
 * {@code false}. The business day is the owner's registration date (supplied or
 * defaulted, rolled off a weekend by {@link BuildOwner}), so the count matches the
 * per-day accumulation used by {@link EnsureDailyLimit}. The count is over the existing
 * owners (the new owner is not yet saved); the threshold is strictly more than 80.
 */
public class AssessBulkSignup {

    private static final int BULK_SIGNUP_THRESHOLD = 80;

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        LocalDate businessDay = owner.getRegistrationDate();
        long createdToday = ownerRepository.findAll().stream()
            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
            .count();
        owner.setBulkSignupWarning(createdToday > BULK_SIGNUP_THRESHOLD);
    }
}

